#!/usr/bin/env node
/**
 * Generates supabase/migrations/20261120100800_permission_catalog.sql from lib/permissions.ts
 * and lib/modules.ts, so SQL (effective_permissions, effective_modules, role template seeding)
 * and TypeScript can never disagree about keys, modules, professions or templates.
 * lib/permissions.test.ts re-checks the generated file against the TS source.
 *
 *   node scripts/gen-permission-catalog.mjs
 */
import fs from "node:fs";
import path from "node:path";
import { ROOT } from "./lib/db.mjs";
import { PERMISSION_CATALOG, ROLE_TEMPLATES } from "../lib/permissions.ts";
import { MODULES, MODULE_KEYS } from "../lib/modules.ts";

const q = (s) => (s == null ? "null" : `'${String(s).replaceAll("'", "''")}'`);
const arr = (a) => (a && a.length ? `array[${a.map(q).join(", ")}]::text[]` : "null");
const BUSINESS_TYPES = ["clinic", "clinic_pharmacy", "pharmacy"];

const moduleRows = MODULE_KEYS.map((k) => {
  const m = MODULES[k];
  const defaultOn = BUSINESS_TYPES.filter((bt) => m.defaultOn(bt));
  return `  (${q(k)}, ${arr([...m.businessTypes])}, ${arr([...m.requires])}, ${q(m.planFeature ?? null)}, ${arr(defaultOn)})`;
});
const keyRows = Object.entries(PERMISSION_CATALOG).map(([k, d]) =>
  `  (${q(k)}, ${q(d.section)}, ${q(d.module ?? null)}, ${arr(d.requiresProfession ? [...d.requiresProfession] : null)}, ${d.storeScoped ? "true" : "false"})`);
const tplRows = ROLE_TEMPLATES.map((t) =>
  `  (${q(t.key)}, ${q(t.name)}, ${q(t.homeRoute)}, ${t.seeded ? "true" : "false"}, ${arr([...t.permissions])})`);

const sql = `-- =============================================================================
-- 0009 PERMISSION & MODULE CATALOG (GENERATED by scripts/gen-permission-catalog.mjs from
-- lib/permissions.ts and lib/modules.ts; do not hand-edit, regenerate instead)
-- Platform reference data used by effective_modules(), effective_permissions() and
-- seed_role_templates(). TS/SQL parity is asserted by lib/permissions.test.ts.
-- A CHANGED catalog must ship as a NEW generated migration, never by editing this one.
-- =============================================================================

create table module_catalog (
  key              text primary key,
  business_types   text[] not null,
  requires         text[],
  plan_feature     text,
  default_on_types text[]
);
insert into module_catalog (key, business_types, requires, plan_feature, default_on_types) values
${moduleRows.join(",\n")};

create table permission_catalog (
  key                  text primary key,
  section              text not null,
  module_key           text references module_catalog (key),
  requires_profession  text[],
  store_scoped         boolean not null default false
);
insert into permission_catalog (key, section, module_key, requires_profession, store_scoped) values
${keyRows.join(",\n")};

create table role_templates (
  key          text primary key,
  name         text not null,
  home_route   text not null,
  seeded       boolean not null,
  permissions  text[] not null
);
insert into role_templates (key, name, home_route, seeded, permissions) values
${tplRows.join(",\n")};

-- Every template permission must exist in the catalog.
do $$ begin
  if exists (select 1 from role_templates t, unnest(t.permissions) p
              where p not in (select key from permission_catalog)) then
    raise exception 'role_templates reference unknown permission keys';
  end if;
end $$;

comment on table module_catalog     is 'Platform reference: modules (mirror of lib/modules.ts).';
comment on table permission_catalog is 'Platform reference: permission keys (mirror of lib/permissions.ts). requires_profession = clinical key, effective only with a verified credential.';
comment on table role_templates     is 'Platform reference: role templates copied into each tenant at provisioning (seeded = true) or offered when adding staff.';

alter table module_catalog     enable row level security;
alter table permission_catalog enable row level security;
alter table role_templates     enable row level security;
revoke insert, update, delete on module_catalog, permission_catalog, role_templates from service_role;
`;

const out = path.join(ROOT, "supabase", "migrations", "20261120100800_permission_catalog.sql");
fs.writeFileSync(out, sql);
console.log(`wrote ${path.relative(ROOT, out)}: ${moduleRows.length} modules, ${keyRows.length} permission keys, ${tplRows.length} role templates`);
